// Leaf node types
export type HexIntegerLiteral = Terminal<TSKindId.HexIntegerLiteral, string>;
export type True = TSKindId.True;
export type False = TSKindId.False;
export type StringFragment = Terminal<TSKindId.StringFragment, string>;
export type MultilineStringFragment = Terminal<TSKindId.MultilineStringFragment, string>;
export type NullLiteral = TSKindId.NullLiteral;
export type UnderscorePattern = TSKindId.UnderscorePattern;
export type RequiresModifier = TSKindId.TransitiveKeyword | TSKindId.StaticKeyword;
export type Asterisk = TSKindId.Asterisk;
export type IntegralType =
	| TSKindId.ByteKeyword
	| TSKindId.ShortKeyword
	| TSKindId.IntKeyword
	| TSKindId.LongKeyword
	| TSKindId.CharKeyword;
export type FloatingPointType = TSKindId.FloatKeyword | TSKindId.DoubleKeyword;
export type BooleanType = TSKindId.BooleanType;
export type VoidType = TSKindId.VoidType;
export type This = TSKindId.This;
export type Super = TSKindId.Super;
export type Identifier = Terminal<TSKindId.Identifier, string>;
export type DecimalIntegerLiteralArm1 = Terminal<TSKindId.DecimalIntegerLiteralArm1, string>;
export type DecimalIntegerLiteralArm2 = Terminal<TSKindId.DecimalIntegerLiteralArm2, string>;
export type DecimalFloatingPointLiteralArm4Arm1 = Terminal<TSKindId.DecimalFloatingPointLiteralArm4Arm1, string>;
export type DecimalFloatingPointLiteralArm4Arm2 = Terminal<TSKindId.DecimalFloatingPointLiteralArm4Arm2, string>;
export type HexFloatingPointLiteralArm1 = Terminal<TSKindId.HexFloatingPointLiteralArm1, string>;
export type TextBlockWhiteSpace = Terminal<TSKindId.TextBlockWhiteSpace, string>;
export type Tight = TSKindId.Tight;
export type Space = TSKindId.Space;
export type Tab = TSKindId.Tab;
export type Newline = TSKindId.Newline;
export type Blankline = TSKindId.Blankline;
export type DoubleBlankline = TSKindId.DoubleBlankline;
export type Indent = TSKindId.Indent;
export type Dedent = TSKindId.Dedent;

// Supertype unions
export type Literal =
	| DecimalIntegerLiteral
	| HexIntegerLiteral
	| OctalIntegerLiteral
	| BinaryIntegerLiteral
	| DecimalFloatingPointLiteral
	| HexFloatingPointLiteral
	| True
	| False
	| CharacterLiteral
	| StringLiteral
	| NullLiteral;

export type DecimalIntegerLiteral = DecimalIntegerLiteralArm1 | DecimalIntegerLiteralArm2;

export type StringLiteral = StringLiteralLine | StringLiteralTextBlock;

export type EscapeSequence =
	| EscapeSequenceArm1
	| EscapeSequenceArm2
	| EscapeSequenceArm3
	| EscapeSequenceArm4
	| EscapeSequenceArm5;

export type Expression =
	| AssignmentExpression
	| BinaryExpression
	| InstanceofExpression
	| LambdaExpression
	| TernaryExpression
	| UpdateExpression
	| PrimaryExpression
	| UnaryExpression
	| CastExpression
	| SwitchExpression;

export type UpdateExpression = UpdateExpressionPostfix | UpdateExpressionPrefix;

export type PrimaryExpression =
	| Literal
	| ClassLiteral
	| This
	| Identifier
	| ParenthesizedExpression
	| ObjectCreationExpression
	| FieldAccess
	| ArrayAccess
	| MethodInvocation
	| MethodReference
	| ArrayCreationExpression
	| TemplateExpression;

export type Statement =
	| Declaration
	| ExpressionStatement
	| LabeledStatement
	| IfStatement
	| WhileStatement
	| ForStatement
	| EnhancedForStatement
	| Block
	| Semi
	| AssertStatement
	| DoStatement
	| BreakStatement
	| ContinueStatement
