export interface JavaTypeMap extends GrammarTypeMap {
	readonly namespaces: NamespaceMap;
	readonly empty:
		| { readonly node: Program; readonly empty: EmptyProgram }
		| { readonly node: Program.Bound; readonly empty: EmptyProgram }
		| { readonly node: Program.Parsed; readonly empty: EmptyProgram.Parsed }
		| { readonly node: ArgumentList; readonly empty: EmptyArgumentList }
		| { readonly node: ArgumentList.Bound; readonly empty: EmptyArgumentList }
		| { readonly node: ArgumentList.Parsed; readonly empty: EmptyArgumentList.Parsed }
		| { readonly node: TypeArguments; readonly empty: EmptyTypeArguments }
		| { readonly node: TypeArguments.Bound; readonly empty: EmptyTypeArguments }
		| { readonly node: TypeArguments.Parsed; readonly empty: EmptyTypeArguments.Parsed }
		| { readonly node: RecordPatternBody; readonly empty: EmptyRecordPatternBody }
		| { readonly node: RecordPatternBody.Bound; readonly empty: EmptyRecordPatternBody }
		| { readonly node: RecordPatternBody.Parsed; readonly empty: EmptyRecordPatternBody.Parsed }
		| { readonly node: Block; readonly empty: EmptyBlock }
		| { readonly node: Block.Bound; readonly empty: EmptyBlock }
		| { readonly node: Block.Parsed; readonly empty: EmptyBlock.Parsed }
		| { readonly node: BreakStatement; readonly empty: EmptyBreakStatement }
		| { readonly node: BreakStatement.Bound; readonly empty: EmptyBreakStatement }
		| { readonly node: BreakStatement.Parsed; readonly empty: EmptyBreakStatement.Parsed }
		| { readonly node: ContinueStatement; readonly empty: EmptyContinueStatement }
		| { readonly node: ContinueStatement.Bound; readonly empty: EmptyContinueStatement }
		| { readonly node: ContinueStatement.Parsed; readonly empty: EmptyContinueStatement.Parsed }
		| { readonly node: ReturnStatement; readonly empty: EmptyReturnStatement }
		| { readonly node: ReturnStatement.Bound; readonly empty: EmptyReturnStatement }
		| { readonly node: ReturnStatement.Parsed; readonly empty: EmptyReturnStatement.Parsed }
		| { readonly node: ElementValueArrayInitializer; readonly empty: EmptyElementValueArrayInitializer }
		| { readonly node: ElementValueArrayInitializer.Bound; readonly empty: EmptyElementValueArrayInitializer }
		| { readonly node: ElementValueArrayInitializer.Parsed; readonly empty: EmptyElementValueArrayInitializer.Parsed }
		| { readonly node: ModuleBody; readonly empty: EmptyModuleBody }
		| { readonly node: ModuleBody.Bound; readonly empty: EmptyModuleBody }
		| { readonly node: ModuleBody.Parsed; readonly empty: EmptyModuleBody.Parsed }
		| { readonly node: EnumBody; readonly empty: EmptyEnumBody }
		| { readonly node: EnumBody.Bound; readonly empty: EmptyEnumBody }
		| { readonly node: EnumBody.Parsed; readonly empty: EmptyEnumBody.Parsed }
		| { readonly node: ClassBody; readonly empty: EmptyClassBody }
		| { readonly node: ClassBody.Bound; readonly empty: EmptyClassBody }
		| { readonly node: ClassBody.Parsed; readonly empty: EmptyClassBody.Parsed }
		| { readonly node: ConstructorBody; readonly empty: EmptyConstructorBody }
		| { readonly node: ConstructorBody.Bound; readonly empty: EmptyConstructorBody }
		| { readonly node: ConstructorBody.Parsed; readonly empty: EmptyConstructorBody.Parsed }
		| { readonly node: AnnotationTypeBody; readonly empty: EmptyAnnotationTypeBody }
		| { readonly node: AnnotationTypeBody.Bound; readonly empty: EmptyAnnotationTypeBody }
		| { readonly node: AnnotationTypeBody.Parsed; readonly empty: EmptyAnnotationTypeBody.Parsed }
		| { readonly node: InterfaceBody; readonly empty: EmptyInterfaceBody }
		| { readonly node: InterfaceBody.Bound; readonly empty: EmptyInterfaceBody }
		| { readonly node: InterfaceBody.Parsed; readonly empty: EmptyInterfaceBody.Parsed }
		| { readonly node: ArrayInitializer; readonly empty: EmptyArrayInitializer }
		| { readonly node: ArrayInitializer.Bound; readonly empty: EmptyArrayInitializer }
		| { readonly node: ArrayInitializer.Parsed; readonly empty: EmptyArrayInitializer.Parsed }
		| { readonly node: FormalParametersList; readonly empty: EmptyFormalParametersList }
		| { readonly node: FormalParametersList.Bound; readonly empty: EmptyFormalParametersList }
		| { readonly node: FormalParametersList.Parsed; readonly empty: EmptyFormalParametersList.Parsed };
	readonly trivia: BlockComment | Layout | LineComment;
}

export type NodeMethodsOf = NodeMethods & HoldsTrivia<JavaTypeMap['trivia']>;
export type TriviaSetterOf<Self> = TriviaSetter<Self, JavaTypeMap['trivia']>;
export type InnerTrivia<N> = GrammarInnerTrivia<N, JavaTypeMap['trivia']>;

